questionvariables.text:
/* Q1 équation chimique (2pt) */
tans1:"CH4 + 2 O2 -> CO2 + 2 H2O";
tarr1:"->";
trf1:[[[1,"C"],[4,"H"]],[[2,"O"]]];
trk1:[1,2];
trc1:[0,0];
trg1:[];
tpf1:[[[1,"C"],[2,"O"]],[[2,"H"],[1,"O"]]];
tpk1:[1,2];
tpc1:[0,0];
tpg1:[];
tfg1:"";
ttype1:"combustion";
has_rg1:is(length(trg1)>0);
has_pg1:is(length(tpg1)>0);

feedbackvariables.text:
/* Flèche — tarr1 stocke directement la flèche (pas de ssearch sur tans encodé) */
fleche_att1: tarr1;
fleche_el1: ans_arr;
vf1: if (fleche_el1 = fleche_att1) then 1 else 0;
/* Comptages */
nb_rt1: length(trf1); nb_rs1: length(ans_rf1);
nb_pt1: length(tpf1); nb_ps1: length(ans_pf1);
/* Charges */
sch_rt1: sum(trk1[i]*trc1[i],i,1,length(trk1));
sch_pt1: sum(tpk1[i]*tpc1[i],i,1,length(tpk1));
sch_rs1: if listp(ans_rk1) and listp(ans_rc1) and length(ans_rk1)=length(ans_rc1) and length(ans_rk1)>0 then sum(ans_rk1[i]*ans_rc1[i],i,1,length(ans_rk1)) else 99;
sch_ps1: if listp(ans_pk1) and listp(ans_pc1) and length(ans_pk1)=length(ans_pc1) and length(ans_pk1)>0 then sum(ans_pk1[i]*ans_pc1[i],i,1,length(ans_pk1)) else 99;
/* Coefficients */
vcs1: if (trk1=ans_rk1) and (tpk1=ans_pk1) then 1 else 0;
k1: if listp(ans_rk1) and length(ans_rk1)>0 and ans_rk1[1]#0 and trk1[1]#0 then ans_rk1[1]/trk1[1] else 1;
vcp1: if listp(ans_rk1) and listp(ans_pk1) then is(k1*trk1=ans_rk1) and is(k1*tpk1=ans_pk1) else false;
/* Groupes fonctionnels */
lrg1: if listp(stackjson_parse(ans_rg1)) then stackjson_parse(ans_rg1) else [];
lpg1: if listp(stackjson_parse(ans_pg1)) then stackjson_parse(ans_pg1) else [];
set_rgt1: setify(trg1); set_rgs1: setify(lrg1);
set_pgt1: setify(tpg1); set_pgs1: setify(lpg1);
mq_rg1: listify(setdifference(set_rgt1,set_rgs1));
mq_pg1: listify(setdifference(set_pgt1,set_pgs1));
ok_rg1: length(mq_rg1)=0; ok_pg1: length(mq_pg1)=0;
ok_g1: if ok_rg1 and ok_pg1 then 1 else 0;
/* Formules sécurisées pour EqualComAss */
srf1: if listp(ans_rf1) and length(ans_rf1)>0 and listp(ans_rf1[1]) then sort(map(sort,ans_rf1)) else [];
spf1: if listp(ans_pf1) and length(ans_pf1)>0 and listp(ans_pf1[1]) then sort(map(sort,ans_pf1)) else [];
strf1: sort(map(sort,trf1));
stpf1: sort(map(sort,tpf1));
